import{c as e,Q as r,j as o,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"SKILL 同質性盤點與整併評估規格書","description":"","frontmatter":{"title":"SKILL 同質性盤點與整併評估規格書","date":"2026-06-07T00:00:00.000Z","status":"已裁（2026-06-07）— ship-review 維持獨立已核准；P-A/M2/M1 保留提案不執行；本 session 不動 .claude/skills/，規格書為唯一交付物","branch":"feature/skill-evolution-audit","disposition_authority":"所有 merge/delete 為破壞性動作（改 RESOLVER routing 不可逆）→ core.md APPLY 段 gate，逐項 AskUserQuestion 待核准","mnilax_corpus":"research/tweets/2026-05-{01,05,09,11}-@Mnilax-*.md（skill 數量過載論點）","scope":".claude/skills/（27 個 SKILL.md；不含 plugin/command skills 如 grill/quick-pr/deep-research）","source_plan":"research/reports/2026-06-07-deep-practices-v2-execution-plan.md","type":"evaluation-spec"},"headers":[],"relativePath":"research/reports/2026-06-07-skill-consolidation-spec.md","filePath":"research/reports/2026-06-07-skill-consolidation-spec.md","lastUpdated":1780842316000}'),i={name:"research/reports/2026-06-07-skill-consolidation-spec.md"};function a(d,t,n,l,h,c){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="skill-同質性盤點與整併評估規格書" tabindex="-1">SKILL 同質性盤點與整併評估規格書 <a class="header-anchor" href="#skill-同質性盤點與整併評估規格書" aria-label="Permalink to &quot;SKILL 同質性盤點與整併評估規格書&quot;">​</a></h1><blockquote><p><strong>任務</strong>：(1) 對 <code>ship-review</code> 跑 skill-evolution 評估是否合併；(2) 盤點全部 27 SKILL 同質性，評估刪除/合併；(3) 寫成符合 Self-Evolving + SKILL 設計的規格書。 <strong>核心紀律</strong>：本規格書是 <strong>evaluation + 提案</strong>，非授權執行。刪/併改 RESOLVER routing 且不可逆 → 每條標「提案（待核准）」，本 session 除本檔外不動 <code>.claude/skills/</code> 內容（advisor + core.md APPLY 破壞性 gate）。 <strong>使用者前置約束</strong>：仍以 <strong>Sub Agent</strong> 為 workspace 主力（<strong>不採 Agent Teams</strong>）→ 排除 deep-practices-v2 計劃書 Q2/P2-2。</p></blockquote><hr><h2 id="第零節-分母與方法" tabindex="-1">第零節：分母與方法 <a class="header-anchor" href="#第零節-分母與方法" aria-label="Permalink to &quot;第零節：分母與方法&quot;">​</a></h2><h3 id="_0-1-分母定案" tabindex="-1">0.1 分母定案 <a class="header-anchor" href="#_0-1-分母定案" aria-label="Permalink to &quot;0.1 分母定案&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find .claude/skills -name SKILL.md | wc -l  →  27</span></span></code></pre></div><p>27 個 SKILL.md。<code>ls</code> 顯示 28 目錄但其一為 <code>RESOLVER.md</code>（非 skill 目錄）。SessionStart 報「27 skills」一致。</p><p><strong><code>disable-model-invocation: true</code>（3 個，僅 <code>/cmd</code> 觸發，不參與 description 自動 routing）</strong>：</p><ul><li><code>harness-meta</code>、<code>security-compliance</code>、<code>ship-review</code></li></ul><h3 id="_0-2-方法-套用-advisor-校準" tabindex="-1">0.2 方法（套用 advisor 校準） <a class="header-anchor" href="#_0-2-方法-套用-advisor-校準" aria-label="Permalink to &quot;0.2 方法（套用 advisor 校準）&quot;">​</a></h3><ol><li><code>skill-evolution:scan</code> 是<strong>單 skill</strong> 7 維品質評分，<strong>答不了「誰跟誰重複」</strong> → 自建 <strong>cross-skill 同質性矩陣</strong>。</li><li>先<strong>群聚</strong>（5 群）再<strong>群內兩兩比</strong>，不盲掃 27×27。</li><li>比對四維：<strong>(a) domain 重疊 (b) trigger 詞碰撞 (c) allowed-tools 重疊 (d) body 功能冗餘</strong>。</li><li><strong>merge 判準（鐵律）</strong>：X 併入 Y ⟺ X <strong>無</strong> Y 沒有的獨特能力 <strong>且</strong> trigger/domain 重疊到使用者會混淆。有獨特能力但 skill 數冗 → 優先「降為子命令」而非 delete（保能力減 skill 數）。</li></ol><hr><h2 id="第零節之二-mnilax「過多-skill-反傷」論點接地-使用者指定參考" tabindex="-1">第零節之二：Mnilax「過多 SKILL 反傷」論點接地（使用者指定參考） <a class="header-anchor" href="#第零節之二-mnilax「過多-skill-反傷」論點接地-使用者指定參考" aria-label="Permalink to &quot;第零節之二：Mnilax「過多 SKILL 反傷」論點接地（使用者指定參考）&quot;">​</a></h2><blockquote><p>使用者指出 Mnilax 主張過多 SKILL 影響效率，要求納入整併參考。通讀 9 篇 Mnilax 推文（researcher 抽取 → 主對話親 grep 驗證 5 個關鍵數字屬實），並<strong>對齊本 workspace 實際架構</strong>（advisor 校準：別把高估數字直接套用，也別用架構區分把使用者 steer 解釋掉）。</p></blockquote><h3 id="_0-2-1-mnilax-原始主張-親驗屬實" tabindex="-1">0-2.1 Mnilax 原始主張（親驗屬實） <a class="header-anchor" href="#_0-2-1-mnilax-原始主張-親驗屬實" aria-label="Permalink to &quot;0-2.1 Mnilax 原始主張（親驗屬實）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>論點</th><th>數字</th><th>親驗來源</th></tr></thead><tbody><tr><td>active skill 甜蜜點上限</td><td><strong>5–7 個</strong>，超過 = overhead &gt; value</td><td><code>897712:321</code> 逐字</td></tr><tr><td>9+ active skills overhead</td><td><strong>~13,500 tokens/task</strong>（每個 SKILL.md 800–2,500 tok「以防萬一」載入）</td><td><code>556522:97</code> + <code>897712:323</code></td></tr><tr><td>一次裝 23 個</td><td>第一個 prompt 前耗盡 context window</td><td><code>897712:297</code></td></tr><tr><td>規則/條目過多 → compliance 衰退</td><td>14 條規則 → 76%→52%；CLAUDE.md &gt;200 行急降</td><td><code>155938</code>（與 core.md 既有紀律一致）</td></tr><tr><td>skill 淘汰標準</td><td>「adds more context than it returns in value」</td><td><code>897712</code></td></tr></tbody></table><h3 id="_0-2-2-架構對齊-mnilax-的「body-全常駐」模型-vs-本-workspace-的-progressive-disclosure" tabindex="-1">0-2.2 架構對齊：Mnilax 的「body 全常駐」模型 vs 本 workspace 的 progressive disclosure <a class="header-anchor" href="#_0-2-2-架構對齊-mnilax-的「body-全常駐」模型-vs-本-workspace-的-progressive-disclosure" aria-label="Permalink to &quot;0-2.2 架構對齊：Mnilax 的「body 全常駐」模型 vs 本 workspace 的 progressive disclosure&quot;">​</a></h3><p><strong>關鍵區分（決定數字是否適用）</strong>——本 workspace 的 skill 成本分三層：</p><table tabindex="0"><thead><tr><th>層</th><th style="text-align:center;">是否每 session 常駐</th><th style="text-align:center;">隨 skill 數成長？</th><th>本 workspace 實測</th></tr></thead><tbody><tr><td><strong>skill descriptions</strong>（harness 原生注入；見本 session transcript 頂端「The following skills are available」清單）</td><td style="text-align:center;">✅ 常駐</td><td style="text-align:center;"><strong>是</strong></td><td>27 description 行 = <strong>9,122 字元 ≈ 2,600 tokens</strong>；扣 2 個 DMI（不注入）→ <strong>25 個貢獻常駐稅</strong></td></tr><tr><td><strong>RESOLVER.md</strong>（session-init.sh:261 注入指針，routing 時讀）</td><td style="text-align:center;">指針常駐 / 本體按需</td><td style="text-align:center;">是（27 條目）</td><td>14,127 byte ≈ 3,500 tok，cache 攤銷</td></tr><tr><td><strong>SKILL.md body</strong>（觸發時才 Read）</td><td style="text-align:center;">❌ 只付用到的</td><td style="text-align:center;"><strong>否</strong></td><td>親驗 <code>session-init.sh:257-261</code> 只數數量 + 注入指針，body 不常駐</td></tr></tbody></table><p><strong>誠實調和（advisor 校準）</strong>：</p><ul><li>Mnilax <strong>頭條數字 13,500 tok/task 對本 workspace 高估</strong>——因 body 採 progressive disclosure（觸發才載），非「9 skills × 1,500 全常駐」。✓</li><li>但 <strong>Mnilax 原則仍適用，只是機制不同</strong>： <ol><li><strong>description 常駐稅真實且隨數量成長</strong>（25 skill × description = ~2,600 tok 每 session，每 turn 重付）。</li><li><strong>routing / decision load 直接適用</strong>——對應 Mnilax「14 條規則 → compliance 76%→52%」（這是<strong>決策負荷</strong>非 token）。本 workspace <strong>已顯化兩個碰撞</strong>（見下）。</li><li><strong>維護成本</strong>：27 個 SKILL.md + GOTCHAS + RESOLVER 同步。</li></ol></li></ul><h3 id="_0-2-3-mnilax「太多→混淆」在本-workspace-的自有證據-非外推-是實測碰撞" tabindex="-1">0-2.3 Mnilax「太多→混淆」在本 workspace 的自有證據（非外推，是實測碰撞） <a class="header-anchor" href="#_0-2-3-mnilax「太多→混淆」在本-workspace-的自有證據-非外推-是實測碰撞" aria-label="Permalink to &quot;0-2.3 Mnilax「太多→混淆」在本 workspace 的自有證據（非外推，是實測碰撞）&quot;">​</a></h3><p>本盤點獨立發現的 routing 碰撞，正是 Mnilax decision-load 論點的 workspace 顯化：</p><table tabindex="0"><thead><tr><th>碰撞</th><th>證據</th><th>Mnilax 對應</th></tr></thead><tbody><tr><td><code>ship-review</code> vs <code>autoresearch:ship</code> 撞 &quot;ship&quot; 語意</td><td>RESOLVER §214-215 需兩行才勉強區分（交付 vs 審查 gate）</td><td>routing 混淆</td></tr><tr><td>三個 &quot;research&quot; 命名相近（research-hub / overnight-research / media-research）</td><td>字面近、domain 正交，靠 Do NOT 互指消歧</td><td>decision load</td></tr><tr><td>三個 pilot 近乎同構（haiku/sonnet/opus）</td><td>3 條 description 表達同一概念（mode wrapper）</td><td>「adds more context than value」</td></tr></tbody></table><h3 id="_0-2-4-對整併結論的影響-正當化來源更新" tabindex="-1">0-2.4 對整併結論的影響（正當化來源更新） <a class="header-anchor" href="#_0-2-4-對整併結論的影響-正當化來源更新" aria-label="Permalink to &quot;0-2.4 對整併結論的影響（正當化來源更新）&quot;">​</a></h3><p>整併<strong>價值真實但量級小於 Mnilax 頭條</strong>。正當化來源從「省 13,500 tok/task」<strong>改為</strong>：</p><ul><li>(a) 降 description 常駐稅（每整併 1 skill 省 ~100 tok/turn × 全 session）；</li><li>(b) routing 清晰度（消除上述實測碰撞）；</li><li>(c) 維護成本。</li></ul><p>→ 以 <strong>description 稅 + routing 透鏡</strong>重新看，<strong>三 pilot 整併（M1）是最強槓桿</strong>（3 條 description→1，且消同構冗餘）。原「季度級 defer」與使用者 steer（特意引入 Mnilax）+ Mnilax 原則<strong>方向相反</strong> → 第四節改列<strong>張力攤給使用者裁</strong>（見 D-M1）。</p><hr><h2 id="第一節-群聚地圖-27-skill-→-8-群" tabindex="-1">第一節：群聚地圖（27 SKILL → 8 群） <a class="header-anchor" href="#第一節-群聚地圖-27-skill-→-8-群" aria-label="Permalink to &quot;第一節：群聚地圖（27 SKILL → 8 群）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>群</th><th>成員</th><th>群內疑慮</th></tr></thead><tbody><tr><td><strong>G1 Pilots</strong></td><td>haiku-pilot / sonnet-pilot / opus-pilot</td><td>三者近乎同構（model-mode wrapper）→ 最強合併候選</td></tr><tr><td><strong>G2 Research</strong></td><td>research-hub / overnight-research / media-research / autoresearch(+11 subcmd)</td><td>入口重疊；media-research vs media-transcribe 邊界</td></tr><tr><td><strong>G3 Review/Ship/Merge</strong></td><td>review-hub / ship-review / verified-merge</td><td><strong>本任務焦點</strong>；ship-review 路由與 autoresearch:ship 撞名</td></tr><tr><td><strong>G4 Meta/Self-Evolving</strong></td><td>skill-evolution / autoload-evolution / harness-meta / eval-designer</td><td>自我進化閉環三件，邊界需驗</td></tr><tr><td><strong>G5 Security</strong></td><td>security-compliance / iac-review / (autoresearch:security)</td><td>合規 vs 靜態審查 vs app-sec 三層</td></tr><tr><td><strong>G6 Ops</strong></td><td>sre / db-ops / finops</td><td>運維三分，domain 各異</td></tr><tr><td><strong>G7 Gap/Consensus</strong></td><td>gap-vote / token-waste-audit / tech-strategy</td><td>各自獨立分析器</td></tr><tr><td><strong>G8 Atomic 工具</strong></td><td>diagram-gen / spec-implement / media-transcribe / webshot / sia</td><td>單一職責，低重疊</td></tr></tbody></table><hr><h2 id="第二節-ship-review-專項評估-任務焦點" tabindex="-1">第二節：ship-review 專項評估（任務焦點） <a class="header-anchor" href="#第二節-ship-review-專項評估-任務焦點" aria-label="Permalink to &quot;第二節：ship-review 專項評估（任務焦點）&quot;">​</a></h2><h3 id="_2-1-skill-evolution-7-維品質評分" tabindex="-1">2.1 skill-evolution 7 維品質評分 <a class="header-anchor" href="#_2-1-skill-evolution-7-維品質評分" aria-label="Permalink to &quot;2.1 skill-evolution 7 維品質評分&quot;">​</a></h3><table tabindex="0"><thead><tr><th>維度</th><th>評分</th><th>佐證</th></tr></thead><tbody><tr><td>Trigger 清晰度</td><td>5</td><td>description 雙段 + 4 觸發詞 + 2 Do NOT 反例</td></tr><tr><td>工具宣告完整性</td><td>5</td><td><code>Read, Grep, Glob, Bash</code> 與實際一致（fan-out 經 Agent 但本體只讀）</td></tr><tr><td>Guard/Verify</td><td>4</td><td>有「跳過 fan-out 條件」機械門檻；Phase B/C 合成屬 LLM 判斷</td></tr><tr><td>Fallback 路徑</td><td>5</td><td>Sub-agent 失敗 rollback 表（crash/critical/timeout 三類）</td></tr><tr><td>行數合規</td><td>5</td><td>117 行 ≪ 350</td></tr><tr><td>版本/日期</td><td>5</td><td>version 1.0.0 + review-by 2026-08-23</td></tr><tr><td>Gotcha 記錄</td><td>3</td><td>body 內含 1 條明示 Gap（sub-agent failure rollback）</td></tr><tr><td><strong>加總</strong></td><td><strong>32 → Tier A</strong></td><td>品質本身優秀，<strong>非品質問題</strong></td></tr></tbody></table><blockquote><p>ship-review <strong>品質達 Tier A</strong>，合併與否不取決於品質，取決於<strong>同質性與獨特能力</strong>（下節）。</p></blockquote><h3 id="_2-2-g3-同質性矩陣-review-hub-ship-review-verified-merge" tabindex="-1">2.2 G3 同質性矩陣（review-hub / ship-review / verified-merge） <a class="header-anchor" href="#_2-2-g3-同質性矩陣-review-hub-ship-review-verified-merge" aria-label="Permalink to &quot;2.2 G3 同質性矩陣（review-hub / ship-review / verified-merge）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>對</th><th style="text-align:center;">(a)domain重疊</th><th style="text-align:center;">(b)trigger碰撞</th><th style="text-align:center;">(c)tools重疊</th><th style="text-align:center;">(d)功能冗餘</th><th>結論</th></tr></thead><tbody><tr><td>ship-review × review-hub</td><td style="text-align:center;">高（都做 code 審查）</td><td style="text-align:center;">低（ship vs review-hub:）</td><td style="text-align:center;">100% (R/G/G/B)</td><td style="text-align:center;">部分（review-hub:commit 三維 vs ship 三 agent fan-out）</td><td>見 2.3</td></tr><tr><td>ship-review × verified-merge</td><td style="text-align:center;">中（都在 ship 前置）</td><td style="text-align:center;">低</td><td style="text-align:center;">100%</td><td style="text-align:center;">低（verified-merge 純機械 gate 不做 review）</td><td>互補，不併</td></tr><tr><td>review-hub × verified-merge</td><td style="text-align:center;">低</td><td style="text-align:center;">低</td><td style="text-align:center;">100%</td><td style="text-align:center;">低</td><td>互補，不併</td></tr></tbody></table><h3 id="_2-3-ship-review-獨特能力鑑定-merge-判準核心" tabindex="-1">2.3 ship-review 獨特能力鑑定（merge 判準核心） <a class="header-anchor" href="#_2-3-ship-review-獨特能力鑑定-merge-判準核心" aria-label="Permalink to &quot;2.3 ship-review 獨特能力鑑定（merge 判準核心）&quot;">​</a></h3><p>ship-review 三項能力，逐一驗是否被 review-hub/verified-merge 覆蓋：</p><table tabindex="0"><thead><tr><th>ship-review 能力</th><th style="text-align:center;">review-hub 覆蓋？</th><th style="text-align:center;">verified-merge 覆蓋？</th><th>判定</th></tr></thead><tbody><tr><td>① 三維平行 fan-out（code-reviewer + <strong>security-auditor</strong> + <strong>test-engineer</strong> 一次）</td><td style="text-align:center;">✗（§Adversarial Review 僅 code 維，無 security/test 並行）</td><td style="text-align:center;">✗</td><td><strong>獨特</strong></td></tr><tr><td>② GO / NO-GO 二元決策</td><td style="text-align:center;">✗（review-hub 輸出分類清單，不下二元 gate 決策）</td><td style="text-align:center;">△（verified-merge 是 ABORT/PASS 但只對機械 gate，非 review 合成）</td><td><strong>獨特</strong></td></tr><tr><td>③ Rollback plan（觸發條件/步驟/RTO）</td><td style="text-align:center;">✗</td><td style="text-align:center;">✗</td><td><strong>獨特</strong></td></tr></tbody></table><p><strong>結論</strong>：ship-review <strong>擁有三項其他 skill 不覆蓋的獨特能力</strong> → 依 merge 判準鐵律<strong>不可 delete、不可單純併入</strong>。</p><h3 id="_2-4-真正的問題-與-autoresearch-ship-的命名-路由碰撞" tabindex="-1">2.4 真正的問題：與 autoresearch:ship 的命名/路由碰撞 <a class="header-anchor" href="#_2-4-真正的問題-與-autoresearch-ship-的命名-路由碰撞" aria-label="Permalink to &quot;2.4 真正的問題：與 autoresearch:ship 的命名/路由碰撞&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>ship-review</th><th>autoresearch:ship</th></tr></thead><tbody><tr><td>觸發</td><td><code>ship-review</code> / 準備發布 / 上線前檢查</td><td><code>autoresearch:ship</code> / 交付發布</td></tr><tr><td>內容</td><td>三 agent fan-out 審查 → GO/NO-GO + rollback</td><td>8-phase universal shipping（code/content/marketing/sales）</td></tr><tr><td>RESOLVER 區分</td><td>「上線前 fan-out 審查」</td><td>「交付發布（PR/部署/內容上線）」</td></tr></tbody></table><p>兩者皆含 &quot;ship&quot; 語意，使用者說「我要 ship 這個 PR」時 routing 有歧義。<strong>這是真實 gap，但解法是釐清 routing 不是合併</strong>（兩者功能正交：一個是「審查 gate」一個是「交付流程」）。</p><h3 id="_2-5-ship-review-處置提案" tabindex="-1">2.5 ship-review 處置提案 <a class="header-anchor" href="#_2-5-ship-review-處置提案" aria-label="Permalink to &quot;2.5 ship-review 處置提案&quot;">​</a></h3><table tabindex="0"><thead><tr><th>選項</th><th>描述</th><th>利</th><th>弊</th></tr></thead><tbody><tr><td><strong>A. 維持獨立</strong>（推薦）</td><td>不動，僅在 RESOLVER 加一行 disambiguation（ship-review=審查 gate / autoresearch:ship=交付流程）</td><td>保留 Tier A 品質 + 獨特能力；零破壞</td><td>skill 數不減（但本就不應為減數砍能力）</td></tr><tr><td>B. 降為 review-hub:ship 子命令</td><td>ship-review 內容移入 review-hub 成 <code>review-hub:ship</code></td><td>skill 數 −1；review 系列收斂單一入口</td><td>review-hub 已 204 行 +117 → 逼近 350；DMI 屬性丟失（review-hub 非 DMI）；fan-out 編排與 review-hub 其他子命令異質</td></tr><tr><td>C. Delete</td><td>移除</td><td>—</td><td><strong>違反 merge 判準</strong>（有獨特能力）→ 排除</td></tr></tbody></table><p><strong>主對話 verdict</strong>：推薦 <strong>A（維持獨立 + RESOLVER disambiguation）</strong>。理由：ship-review 三項獨特能力（multi-agent fan-out / GO-NO-GO / rollback）無替代；降子命令（B）會讓 review-hub 逼近行數上限且混入異質編排邏輯，淨損。唯一真實 gap（與 autoresearch:ship 撞名）用一行 routing 註記解決，成本遠低於合併。</p><blockquote><p><strong>使用者已核准（2026-06-07）：選項 A — ship-review 維持獨立</strong>。RESOLVER disambiguation 加註本 session 不執行（保留提案），日後若觸發實際 routing 混淆再補。</p></blockquote><hr><h2 id="第三節-全-27-skill-同質性盤點-群內裁決" tabindex="-1">第三節：全 27 SKILL 同質性盤點（群內裁決） <a class="header-anchor" href="#第三節-全-27-skill-同質性盤點-群內裁決" aria-label="Permalink to &quot;第三節：全 27 SKILL 同質性盤點（群內裁決）&quot;">​</a></h2><h3 id="g1-pilots-—-haiku-sonnet-opus-pilot-最強合併候選" tabindex="-1">G1 Pilots — haiku/sonnet/opus-pilot（<strong>最強合併候選</strong>） <a class="header-anchor" href="#g1-pilots-—-haiku-sonnet-opus-pilot-最強合併候選" aria-label="Permalink to &quot;G1 Pilots — haiku/sonnet/opus-pilot（**最強合併候選**）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>對</th><th style="text-align:center;">domain</th><th style="text-align:center;">trigger</th><th style="text-align:center;">tools</th><th style="text-align:center;">功能冗餘</th></tr></thead><tbody><tr><td>三者兩兩</td><td style="text-align:center;">高（皆 model-mode wrapper）</td><td style="text-align:center;">低（haiku/sonnet/opus 互斥）</td><td style="text-align:center;">100%（R/G/G/B/TodoWrite）</td><td style="text-align:center;"><strong>高</strong>（結構同構：preflight + escalation gate + mode 宣告）</td></tr></tbody></table><ul><li><strong>同質性</strong>：三者是同一模板的 model 參數化（281/318/356 行，結構平行）。</li><li><strong>獨特能力差異</strong>：僅「成本 vs 品質」定位與 escalation 方向不同（haiku→升級 / opus→reverse-advisor）。</li><li><strong>提案（待核准）</strong>：<strong>M1 — 合併為單一 <code>pilot</code> skill + 三子命令</strong>（<code>pilot:haiku</code> / <code>pilot:sonnet</code> / <code>pilot:opus</code>），共用 preflight 骨架，差異部分分節。 <ul><li>利：skill 數 −2（27→25）；消除三份重複 preflight；單一維護點。</li><li>弊：合併後單檔可能 &gt;450 行 body（需壓縮共用段）；觸發詞 <code>haiku</code>/<code>sonnet</code>/<code>opus</code> 需保留為 alias。</li><li><strong>風險</strong>：pilot 是高頻 mode 切換，routing 改動影響日常 → 須 eval gate（model-fit 回歸）。</li><li><strong>判定</strong>：<strong>真合併候選</strong>，但因高頻 routing 影響大 → 列<strong>季度級</strong>，走 autoload-evolution 式 eval gate，不本次執行。</li></ul></li></ul><h3 id="g2-research-—-research-hub-overnight-research-media-research-autoresearch" tabindex="-1">G2 Research — research-hub / overnight-research / media-research / autoresearch <a class="header-anchor" href="#g2-research-—-research-hub-overnight-research-media-research-autoresearch" aria-label="Permalink to &quot;G2 Research — research-hub / overnight-research / media-research / autoresearch&quot;">​</a></h3><table tabindex="0"><thead><tr><th>對</th><th>重疊判定</th><th>處置</th></tr></thead><tbody><tr><td>research-hub × overnight-research</td><td>中：都做 deep research；但 overnight 是<strong>無人值守 6-phase 自動提交</strong>，research-hub 是互動式。Do NOT 已互指</td><td><strong>不併</strong>（自動 vs 互動正交）</td></tr><tr><td>research-hub × media-research</td><td>低：research-hub Do NOT 明指 Twitter/YT→media-research</td><td><strong>不併</strong>（已清楚分界）</td></tr><tr><td>media-research × media-transcribe</td><td>低：research（文字分析）vs transcribe（Whisper 逐字稿），Do NOT 互指</td><td><strong>不併</strong></td></tr><tr><td>autoresearch × research-hub</td><td>低：autoresearch 是<strong>迭代收斂器</strong>（modify→verify→keep），非研究抓取</td><td><strong>不併</strong></td></tr></tbody></table><ul><li><strong>結論</strong>：G2 邊界已用 Do NOT 互指清楚劃分，<strong>無合併候選</strong>。命名 <code>research-hub</code>/<code>overnight-research</code>/<code>media-research</code> 三個 &quot;research&quot; 字面相近但 domain 正交（互動深研/無人值守/外部媒體）。</li><li><strong>觀察項</strong>：三個 &quot;research&quot; 命名易誤觸；RESOLVER 已有 §「研究」分流表，維持。</li></ul><h3 id="g3-review-ship-merge" tabindex="-1">G3 Review/Ship/Merge <a class="header-anchor" href="#g3-review-ship-merge" aria-label="Permalink to &quot;G3 Review/Ship/Merge&quot;">​</a></h3><p>見第二節。<strong>review-hub / ship-review / verified-merge 三者互補，無合併</strong>（ship-review 提案 A 維持獨立 + RESOLVER disambiguation）。</p><h3 id="g4-meta-self-evolving-—-skill-evolution-autoload-evolution-harness-meta-eval-designer" tabindex="-1">G4 Meta/Self-Evolving — skill-evolution / autoload-evolution / harness-meta / eval-designer <a class="header-anchor" href="#g4-meta-self-evolving-—-skill-evolution-autoload-evolution-harness-meta-eval-designer" aria-label="Permalink to &quot;G4 Meta/Self-Evolving — skill-evolution / autoload-evolution / harness-meta / eval-designer&quot;">​</a></h3><table tabindex="0"><thead><tr><th>對</th><th>domain</th><th>重疊判定</th></tr></thead><tbody><tr><td>skill-evolution × autoload-evolution</td><td>SKILL 品質進化 vs auto-load 規則進化</td><td><strong>不併</strong>：標的不同（skills/ vs CLAUDE.md+4 rules）；Do NOT 互指</td></tr><tr><td>skill-evolution × harness-meta</td><td>SKILL 進化 vs harness 整合入口（HMF/token/add skill）</td><td><strong>部分重疊</strong>：harness-meta 含「Skill 稽核/新增」，與 skill-evolution scan/audit 功能交集</td></tr><tr><td>eval-designer × 其他</td><td>eval function 設計（4 條件）</td><td><strong>不併</strong>：獨立設計器，無重疊</td></tr></tbody></table><ul><li><strong>harness-meta × skill-evolution 重疊細查</strong>：harness-meta <code>:audit</code>（K×M 稽核/skill 稽核）vs skill-evolution <code>:scan</code>/<code>:audit</code>（7 維評分/格式合規）。 <ul><li>harness-meta 是<strong>整合入口</strong>（HMF drift + token + skill 管理 + self-audit 五合一）；skill-evolution 是<strong>專門 SKILL 品質引擎</strong>。</li><li><strong>判定</strong>：harness-meta 的「skill 稽核」應<strong>委派/指向</strong> skill-evolution，非各自實作。<strong>提案 M2（低風險）</strong>：在 harness-meta <code>:audit</code> 段加一行指針「SKILL 品質評分 → skill-evolution:scan」，消除功能重複實作（非合併 skill，是去重邏輯）。<strong>可本次執行（≤5 行，非破壞 routing）</strong>。</li></ul></li></ul><h3 id="g5-security-—-security-compliance-iac-review-autoresearch-security" tabindex="-1">G5 Security — security-compliance / iac-review / autoresearch:security <a class="header-anchor" href="#g5-security-—-security-compliance-iac-review-autoresearch-security" aria-label="Permalink to &quot;G5 Security — security-compliance / iac-review / autoresearch:security&quot;">​</a></h3><table tabindex="0"><thead><tr><th>對</th><th>重疊</th><th>處置</th></tr></thead><tbody><tr><td>security-compliance × iac-review</td><td>低：ISO 27017 合規認證 vs Terraform/K8s 靜態審查。Do NOT 互指（iac→不做合規認證）</td><td><strong>不併</strong></td></tr><tr><td>security-compliance × autoresearch:security</td><td>低：合規 evidence chain vs STRIDE/OWASP red-team。Do NOT 互指</td><td><strong>不併</strong></td></tr><tr><td>iac-review × autoresearch:security</td><td>中：都掃安全；但 iac 是 IaC 靜態 lint，autoresearch:security 是 app-sec red-team</td><td><strong>不併</strong>（層次不同）</td></tr></tbody></table><ul><li><strong>結論</strong>：三層 security（合規/IaC/app-sec）正交，<strong>無合併</strong>。命名清楚。</li></ul><h3 id="g6-ops-—-sre-db-ops-finops" tabindex="-1">G6 Ops — sre / db-ops / finops <a class="header-anchor" href="#g6-ops-—-sre-db-ops-finops" aria-label="Permalink to &quot;G6 Ops — sre / db-ops / finops&quot;">​</a></h3><ul><li>domain 完全正交（運維/DB/成本），Do NOT 三方互指。<strong>無合併</strong>。</li></ul><h3 id="g7-gap-consensus-—-gap-vote-token-waste-audit-tech-strategy" tabindex="-1">G7 Gap/Consensus — gap-vote / token-waste-audit / tech-strategy <a class="header-anchor" href="#g7-gap-consensus-—-gap-vote-token-waste-audit-tech-strategy" aria-label="Permalink to &quot;G7 Gap/Consensus — gap-vote / token-waste-audit / tech-strategy&quot;">​</a></h3><ul><li>gap-vote（多技能投票 executor）/ token-waste-audit（四浪費源診斷）/ tech-strategy（選型 ROI）domain 各異。<strong>無合併</strong>。</li></ul><h3 id="g8-atomic-工具-—-diagram-gen-spec-implement-media-transcribe-webshot-sia" tabindex="-1">G8 Atomic 工具 — diagram-gen / spec-implement / media-transcribe / webshot / sia <a class="header-anchor" href="#g8-atomic-工具-—-diagram-gen-spec-implement-media-transcribe-webshot-sia" aria-label="Permalink to &quot;G8 Atomic 工具 — diagram-gen / spec-implement / media-transcribe / webshot / sia&quot;">​</a></h3><ul><li>五個單一職責工具，零重疊。<strong>無合併</strong>。</li></ul><hr><h2 id="第四節-整併處置總表-提案待核准" tabindex="-1">第四節：整併處置總表（提案待核准） <a class="header-anchor" href="#第四節-整併處置總表-提案待核准" aria-label="Permalink to &quot;第四節：整併處置總表（提案待核准）&quot;">​</a></h2><blockquote><p><strong>使用者裁決（2026-06-07 AskUserQuestion）</strong>：M1 → 只更新規格書不執行；P-A/M2 → 都不執行；ship-review → 同意維持獨立。<strong>本 session 不動 <code>.claude/skills/</code>，規格書為唯一交付物</strong>；下方狀態欄已回填裁決結果。</p></blockquote><table tabindex="0"><thead><tr><th>#</th><th>提案</th><th>類型</th><th>風險</th><th style="text-align:center;">使用者裁決</th><th style="text-align:center;">skill 數變化</th></tr></thead><tbody><tr><td><strong>P-A</strong></td><td>ship-review 維持獨立 + RESOLVER 加一行 disambiguation（vs autoresearch:ship）</td><td>非破壞（僅加註）</td><td>低</td><td style="text-align:center;">✅ ship-review 維持獨立<strong>已核准</strong>；RESOLVER 加註<strong>不執行</strong>（保留提案）</td><td style="text-align:center;">0</td></tr><tr><td><strong>M2</strong></td><td>harness-meta:audit 加指針指向 skill-evolution:scan（去重複實作邏輯）</td><td>非破壞（≤5 行）</td><td>低</td><td style="text-align:center;">⏸️ <strong>不執行</strong>（保留提案）</td><td style="text-align:center;">0</td></tr><tr><td><strong>M1</strong></td><td>三 pilot 合併為 <code>pilot</code> + 3 子命令</td><td><strong>破壞 routing</strong></td><td>中（高頻 mode 切換）</td><td style="text-align:center;">⏸️ <strong>只記錄不執行</strong>（保留提案，見 D-M1）</td><td style="text-align:center;">−2</td></tr><tr><td>—</td><td>G2–G8 其餘</td><td>—</td><td>—</td><td style="text-align:center;">無合併（邊界已清楚）</td><td style="text-align:center;">0</td></tr></tbody></table><h3 id="d-m1-三-pilot-整併時程張力-需使用者裁決" tabindex="-1">D-M1：三 pilot 整併時程張力（需使用者裁決） <a class="header-anchor" href="#d-m1-三-pilot-整併時程張力-需使用者裁決" aria-label="Permalink to &quot;D-M1：三 pilot 整併時程張力（需使用者裁決）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方向</th><th>論據</th></tr></thead><tbody><tr><td><strong>支持本次/盡快做</strong>（Mnilax + 使用者 steer）</td><td>三 pilot 近乎同構（mode wrapper）；description 稅最高槓桿（3→1）；使用者特意引入 Mnilax「過多反傷」；Mnilax 淘汰標準「adds more context than value」直接命中</td></tr><tr><td><strong>支持 defer 季度級</strong>（routing 風險）</td><td>pilot 是高頻 mode 切換（<code>/haiku</code> <code>/sonnet</code> <code>/opus</code> 日常用）；合併改 routing 須 model-fit eval 回歸 ≥5pp 自動 revert（autoload-evolution 式 gate）；合併單檔逼近 450 行需壓縮共用段</td></tr></tbody></table><blockquote><p><strong>不自行 flip</strong>（advisor 紀律）：保留 eval-gate caveat，把方向選擇攤給使用者。建議：<strong>核准方向後</strong>走 autoload-evolution 式閉環（eval gate 保護），而非無 gate 直接合併。</p></blockquote><p><strong>淨結論</strong>：</p><ul><li>27 SKILL 中，<strong>唯一真合併候選 = 三 pilot（M1）</strong>，Mnilax 透鏡下為最強槓桿；時程（本次 vs 季度級）張力 → <strong>使用者裁</strong>（D-M1）。</li><li><strong>無任何 skill 達 delete 門檻</strong>（皆有獨特能力或清楚 domain；Mnilax 高估的 per-task token 不構成 delete 理由）。</li><li>ship-review <strong>不合併</strong>（Tier A + 三獨特能力），僅需 RESOLVER disambiguation（P-A）。</li><li>即時可執行的低風險項：<strong>P-A + M2</strong>（皆非破壞 routing），待使用者核准。</li><li><strong>整併淨價值定性</strong>：以本 workspace progressive-disclosure 架構，整併省的是 description 常駐稅（~2,600 tok 中每項 ~100 tok/turn）+ routing 清晰度 + 維護，<strong>非</strong> Mnilax 頭條的 13,500 tok/task（該數字基於 body 全常駐模型，本 workspace 不適用）。</li></ul><hr><h2 id="第五節-self-evolving-合規-本規格書如何接-skill-自我進化回路" tabindex="-1">第五節：Self-Evolving 合規（本規格書如何接 SKILL 自我進化回路） <a class="header-anchor" href="#第五節-self-evolving-合規-本規格書如何接-skill-自我進化回路" aria-label="Permalink to &quot;第五節：Self-Evolving 合規（本規格書如何接 SKILL 自我進化回路）&quot;">​</a></h2><p>本規格書產出後接入既有閉環（符合 core.md RECORD + skill-evolution Ratchet）：</p><table tabindex="0"><thead><tr><th>Phase</th><th>動作</th></tr></thead><tbody><tr><td>OBSERVE</td><td>本盤點即 cross-skill OBSERVE（27 skill domain/trigger/tool/body 全掃）</td></tr><tr><td>IDENTIFY</td><td>識別 1 真合併候選（M1 pilots）+ 2 低風險去重（P-A/M2）+ 1 routing gap（ship-review vs autoresearch:ship）</td></tr><tr><td>PROPOSE</td><td>第四節總表（每項標類型/風險/可執行性）</td></tr><tr><td>TEST（gate）</td><td>M1 須 model-fit eval 回歸 ≥5pp 自動 revert（autoload-evolution 式）；P-A/M2 須 healthcheck + grep 接地</td></tr><tr><td>APPLY（gate）</td><td><strong>全部待 AskUserQuestion 核准</strong>（破壞性 routing 改動 = core.md APPLY gate）</td></tr><tr><td>RECORD</td><td>核准執行後追加 <code>memory/RATCHET.md</code> + MEMORY session 節</td></tr></tbody></table><h3 id="與-skill-設計標準對齊" tabindex="-1">與 SKILL 設計標準對齊 <a class="header-anchor" href="#與-skill-設計標準對齊" aria-label="Permalink to &quot;與 SKILL 設計標準對齊&quot;">​</a></h3><ul><li>merge 判準引用 SKILL description 雙段（Use when + Do NOT）為 routing 真值來源。</li><li>「降子命令 &gt; delete」原則 = SKILL 設計「保能力減入口」哲學（review-hub/research-hub hub 化先例）。</li><li>不為「減 skill 數」砍獨特能力 = core.md PROPOSE「不為湊數」+ 反 over-engineering。</li></ul><hr><h2 id="附錄-方法稽核" tabindex="-1">附錄：方法稽核 <a class="header-anchor" href="#附錄-方法稽核" aria-label="Permalink to &quot;附錄：方法稽核&quot;">​</a></h2><ul><li>分母：<code>find .claude/skills -name SKILL.md | wc -l = 27</code>（親跑）</li><li>DMI 標記：grep <code>disable-model-invocation: true</code> → harness-meta / security-compliance / ship-review（親跑）</li><li>同質性矩陣四維：domain（roster-domain）/ trigger（description Use when）/ tools（allowed-tools）/ body（grep 結構抽驗）全主對話親驗，未經 sub-agent 中介（unverified_success 閘門）</li><li>advisor 校準（2 輪）：①交付物=規格書非執行；scan 答不了 cross-skill；先群聚再比；merge 判準鐵律；分母定 27。②Mnilax 驗錯層修正：description 才是常駐稅（非 body）；routing 碰撞=Mnilax 原則自有證據；pilots 時程張力攤使用者；DMI 一致性 grep</li><li>Mnilax 接地：researcher 通讀 9 篇 → 主對話親 grep 驗 5 數字（5–7 上限 <code>897712:321</code> / 13,500 <code>556522:97</code> / 23 爆 context <code>897712:297</code> / 14 規則 76→52% / 淘汰標準）全屬實；架構對齊後判定頭條數字高估、原則適用</li><li>DMI 親驗修正：初次 grep 誤判 harness-meta 為 DMI → 逐檔 frontmatter 親驗更正：<strong>DMI 僅 security-compliance + ship-review 兩個</strong>（harness-meta 無 DMI，與 transcript 注入清單一致）→ 貢獻 description 常駐稅 = 25 個</li><li>三層成本親驗：<code>session-init.sh:257-261</code> 只注入指針 body 不常駐；description 9,122 字元 ≈ 2,600 tok 常駐；RESOLVER 14,127 byte 按需</li><li>使用者約束：不採 Agent Teams（排除計劃書 Q2/P2-2）；仍以 Sub Agent 為主力</li></ul>',89)])])}const p=e(i,[["render",a]]);export{u as __pageData,p as default};
